      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Right ear discharge"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Scant clear to slightly yellow discharge noted on a cotton bud the day before."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Ear itching and flaking"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild itch and flaking behind the ears currently."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Right external ear examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Right pinna and tragus very tender to light touch. Canal oedematous, erythematous, moist, with whitish-yellow debris. Tympanic membrane only partly visualised and appears intact; no bulging or obvious middle-ear effusion. No mastoid tenderness or erythema."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Left ear examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild erythema and scaling of the external canal and conchal bowl, consistent with dermatitis; canal patent and tympanic membrane intact. Mild tragal tenderness only on deep palpation."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Peri-auricular skin examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild scaling and erythema in bilateral post-auricular folds, consistent with a seborrhoeic/contact dermatitis mix."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "General and neurological examination findings"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Afebrile and mildly uncomfortable, not in acute distress. No cellulitis, perichondritis, or regional lymphadenopathy. Cranial nerves II–XII grossly intact."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Patient-denied symptoms and history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies upper respiratory symptoms, nasal congestion, tinnitus, vertigo, fever, rigors, facial weakness, severe headache, neck stiffness, trauma, or foreign body in the ear. Reports no weight loss, night sweats, or other systemic symptoms. No diabetes, immunosuppression, or recent systemic antibiotics."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Ibuprofen, over the counter"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "Occasional use; dose and directions not stated."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Ketoconazole 2% shampoo"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "As needed for scalp; frequency not stated.",
            "asNeededBoolean": true
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Sofradex ear drops (dexamethasone 0.05%, framycetin 0.5%, gramicidin 0.005%)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Instil 3 drops into the right ear three times daily for 7 days.",
            "route": {
              "text": "otic"
            },
            "timing": {
              "repeat": {
                "frequency": 3,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 3,
                  "unit": "drops"
                }
              }
            ]
          },
          {
            "text": "May use in the left ear twice daily for 3–5 days if it becomes painful, provided there is no trauma or suspected perforation.",
            "route": {
              "text": "otic"
            },
            "timing": {
              "repeat": {
                "frequency": 2,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 3,
                  "unit": "drops"
                }
              }
            ]
          }
        ],
        "note": [
          {
            "text": "Advised to stop and seek review if sudden marked reduction in hearing, bloody discharge, or trauma occurs."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-2",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-2",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Paracetamol"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "1 g four times daily as needed; maximum 4 g in 24 hours.",
            "route": {
              "text": "oral"
            },
            "asNeededBoolean": true,
            "timing": {
              "repeat": {
                "frequency": 4,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 1,
                  "unit": "g"
                }
              }
            ],
            "maxDosePerPeriod": {
              "numerator": {
                "value": 4,
                "unit": "g"
              },
              "denominator": {
                "value": 24,
                "unit": "h"
              }
            }
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-3",
