            "text": "Resume twice weekly on the scalp and around the external ear skin; do not put into the ear canal.",
            "route": {
              "text": "topical"
            },
            "timing": {
              "repeat": {
                "frequency": 2,
                "period": 1,
                "periodUnit": "wk"
              }
            }
          }
        ]
      }
    }
